package cn.iocoder.yudao.module.amazon.controller.admin.productpricing;
import cn.iocoder.yudao.framework.common.pojo.CommonResult; import cn.iocoder.yudao.module.amazon.controller.admin.products.vo.AmazonProductsReqVO; import cn.iocoder.yudao.module.amazon.service.productpricing.AmazonProductPricingService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.annotation.Resource; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.Map;
/** Amazon Product Pricing 管理接口。 */
@Tag(name="管理后台 - Amazon Product Pricing") @RestController @RequestMapping("/amazon/product-pricing") public class AmazonProductPricingController { @Resource private AmazonProductPricingService service; @PostMapping("/featured-offer-expected-price") @PreAuthorize("@ss.hasPermission('amazon:product-pricing:query')") public CommonResult<Map<String,Object>> featured(@Valid @RequestBody AmazonProductsReqVO r){return CommonResult.success(service.featured(r));} @PostMapping("/competitive-summary") @PreAuthorize("@ss.hasPermission('amazon:product-pricing:query')") public CommonResult<Map<String,Object>> competitive(@Valid @RequestBody AmazonProductsReqVO r){return CommonResult.success(service.competitive(r));} }
